import re

def join(a, b):
    if not a:
        return b
    if not b:
        return a
    if a.endswith('-'):
        return a[:-1] + b
    return a + ' ' + b

def parse(lines):
    blocks = []
    skip = []
    used = set()
    n = len(lines)
    sess = {}
    sl = []
    for j, l in enumerate(lines):
        m = re.match(r'^Session established with server (?P<s>\S+?):\s*(?P<p>.*)$', l)
        if m:
            sess['Server'] = m.group('s')
            sess['Server platform'] = m.group('p').strip()
            sl.append(j)
            continue
        m = re.match(r'^\s+Server Version (?P<v>.+?)\s*$', l)
        if m:
            sess['Server Version'] = m.group('v')
            sl.append(j)
            continue
        m = re.match(r'^\s+Server date/time:\s*(?P<d>.+?)(?:\s{2,}Last access:\s*(?P<a>.+?))?\s*$', l)
        if m:
            sess['Server date/time'] = m.group('d')
            if m.group('a'):
                sess['Last access'] = m.group('a')
            sl.append(j)
    if sess:
        blocks.append({'name': 'session', 'kind': 'kv', 'lines': sl, 'records': [sess]})
        used.update(sl)
    rows_all = []
    tl = []
    cols_final = None
    for d in range(n):
        if d in used or not re.match(r'^\s*-{3,}(?:\s+-{3,})*\s*$', lines[d]):
            continue
        dash = lines[d]
        starts = [m.start() for m in re.finditer(r'-+', dash)]
        def cut(l, k):
            s = starts[k]
            e = starts[k + 1] if k + 1 < len(starts) else None
            return l[s:e].strip() if e is not None else l[s:].strip()
        h = d - 1
        hl = []
        while h >= 0 and lines[h].strip() and h not in used and not re.match(r'^AN[RS]\d{4}', lines[h]):
            hl.insert(0, h)
            h -= 1
        cols = [''] * len(starts)
        for x in hl:
            for k in range(len(starts)):
                cols[k] = join(cols[k], cut(lines[x], k))
        cols = [c if c else 'col%d' % (k + 1) for k, c in enumerate(cols)]
        tl.extend(hl + [d])
        used.update(hl + [d])
        j = d + 1
        rows = []
        while j < n and lines[j].strip() and not re.match(r'^AN[RS]\d{4}', lines[j]):
            vals = [cut(lines[j], k) for k in range(len(starts))]
            if vals[0] == '' and rows:
                r = rows[-1]
                for k, c in enumerate(cols):
                    if vals[k]:
                        r[c] = join(r[c], vals[k])
            else:
                rows.append(dict(zip(cols, vals)))
            tl.append(j)
            used.add(j)
            j += 1
        rows_all.extend(rows)
        cols_final = cols
    if cols_final is not None:
        blocks.append({'name': 'nodes', 'kind': 'table', 'lines': tl, 'records': rows_all})
    for j, l in enumerate(lines):
        if j in used or not l.strip():
            continue
        if re.match(r'^(IBM |Command Line Administrative Interface|\(c\) Copyright|AN[RS]\d{4}[IEWS]|Session established|\s+Server )', l):
            skip.append(j)
    return {'blocks': blocks, 'skip': skip}
